def check_sources(pins=None):
    pins = PRODUCERS if pins is None else pins
    need(bool(pins),'reviewed writer identities missing')
    for name,expected in pins.items():
        need(hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==expected,
             'reviewed writer source drift: '+name)

def native_failure_bound(population):
    """At most one SampleFailure append per selected sample, no append retry.

    Native code is <=64 Unicode code points; six-byte JSON escaping dominates
    UTF-8. The largest partial has a native SHA and a boolean. A short failed
    append occupies a prefix of the same slot, not an extra successful row.
    This does NOT bound unexpected_failure.json, stream output or exceptions.
    """
    need(type(population) is Population,'exact population required')
    check_sources();total=0;rows=[];offset=0
    for split,count in zip(('training','validation','test'),population.counts):
        if count:
            local=count-1
            value=dict(schema='operatormark.darcy_branch_c_v2.generation_failure.v1',
                configuration_sha256='f'*64,benchmark='darcy_branch_c_v2',split=split,
                shard_index=local//population.shard_size,local_index=local,
                global_index=offset+local,sample_id=f'darcy_branch_c_v2/{split}/{local:06d}',
                stratum='binary_32_of_64',stage='tpfa_tangent_d1',code='\0'*64,
                partial=dict(tpfa_passes=False,u_native_sha256='f'*64),
                disposition='retained_not_replaced',record_self_sha256='f'*64)
            width=len(C.canonical_json_bytes(value))+1
            total+=count*width;rows.append(dict(split=split,records=count,row_bytes=width))
        offset+=count
    return dict(bytes=total,rows=rows,partial_append_included=True,
        retries=0,exceptions_included=False,source_hashes=dict(PRODUCERS))

def configuration_template(config, controls, directions, solver, on_failure):
    """Exact-length configuration over the admitted inputs.

    The writer's own builder runs on the actual config, control/direction
    bindings and solver kind. Only fixed-width SHA-256 values (identity map
    values and the determinism-scope hash) are placeholders, so the length is
    exact; the identity KEY sets are the ones the writer will use.
    """
    from operatormark_corpus_v2 import generator as G, pins
    from operatormark_numerics_v2 import pins as drop1
    filled=lambda keys:{k:HEX for k in sorted(keys)}
    record=G.configuration_record(config,controls,directions,solver,on_failure,
        identity={'drop2':filled(pins.drop2_identity()),'drop1':filled(pins.DROP1_PINS),
                  'frozen':filled(drop1.FROZEN_MODULE_PINS)},scope_sha256=HEX)
    return C.canonical_json_bytes(record)

def _checked_template(data, population):
    need(type(data) is bytes,'configuration template bytes required')
    record=C.strict_canonical_json_loads(data);C.validate_self_hash(record,'record_self_sha256')
    layout=record.get('layout');retention=record.get('retention')
    need(record.get('schema')==CONFIGURATION_SCHEMA and type(layout) is dict and type(retention) is dict,
         'configuration template schema')
    need(record.get('n_ref')==population.layout.n_ref and retention.get('option')==population.layout.retention and
         layout.get('counts')==dict(zip(('training','validation','test'),population.counts)) and
         layout.get('shard_size')==population.shard_size and layout.get('synthetic') is population.synthetic and
         record.get('synthetic') is population.synthetic,'configuration template population substitution')
    need(record.get('selection')==[[s,i] for s,i in population.shards()] and record.get('selection_is_complete') is True,
         'configuration template selection must be the whole population')
    policy=record.get('failure_policy')
    need(type(policy) is dict and policy.get('on_failure')=='stop','State 5 writes with on_failure=stop')
    identity=record.get('code_identity')
    need(record.get('determinism_scope_sha256')==HEX and type(identity) is dict and
         set(identity)=={'drop2','drop1','frozen'} and
         all(type(v) is dict and v and all(x==HEX for x in v.values()) for v in identity.values()),
         'template hash slots must be fixed-width placeholders')
    return record

def summary_bound(population):
    """sizing._summary_bound over the population's own layout.

    Its stop_reason slot ('exception:'+64 ASCII bytes) is now enforced by
    generator.exception_stop_reason; every list holds layout sample ids.
    """
    from operatormark_corpus_v2 import layout as L, sizing, d10
    need(type(population) is Population,'exact population required')
    need(set(sizing.GATES[:-1])==set(d10.GATE_NAMES),'summary gate-name domain drift')
    return sizing._summary_bound(L.Layout(population.counts,population.shard_size,population.synthetic))

def configuration_summary_bound(population, template):
    """Configuration and summary are each published once by canonical
    exclusive publication. A failed publish can leave the temporary name and,
    on POSIX, a hard-linked final name: both names are counted, never fewer.
    """
    need(type(population) is Population,'exact population required')
    check_sources(CONFIGURATION_SUMMARY_SOURCES)
    _checked_template(template,population)
    configuration=len(template);summary=summary_bound(population)
    return dict(bytes=2*(configuration+summary),configuration_bytes=configuration,summary_bytes=summary,
        names_per_record=2,source_hashes=dict(CONFIGURATION_SUMMARY_SOURCES))

def run_record_bound(population):
    """run/generation_run.json only; NOT unexpected_failure.json or streams.

    json.dumps(indent=1, ensure_ascii) over closed scalars: 32-character UTC
    ISO stamps, finite floats (<=24-character repr), peak RSS < 2**73, caps
    restricted by generator.check_run_parameters, one timing per selected shard,
    a stop_reason of at most 74 ASCII bytes. Text-mode newline translation is
    counted as CRLF. Written once; a failed write leaves a prefix of this slot.
    """
    from operatormark_corpus_v2 import generator as G
    need(type(population) is Population,'exact population required')
    check_sources(CONFIGURATION_SUMMARY_SOURCES)
    worst_float=-2.2250738585072014e-308
    stamp='9999-12-31T23:59:59.999999+00:00'
    timings=[{'split':'validation','shard':max(c//population.shard_size for c in population.counts),
              'seconds':worst_float,'status':'written'} for _ in population.shards()]
    run=G.run_record(started=stamp,finished=stamp,wall_seconds=worst_float,peak_rss=10**23,
        time_cap_s=worst_float,mem_cap_bytes=2**63-1,timings=timings,stop_reason='exception:'+'X'*64)
    text=json.dumps(run,indent=1)+'\n'
    return dict(bytes=len(text)+text.count('\n'),crlf_counted=True,exceptions_included=False)

