def _readback_subjects(population):
    from operatormark_corpus_v2 import readback as RB
    need(type(population) is Population,'exact population required')
    shards=population.shards();n=population.layout.n_ref
    families=_FAMILIES+((f'u_tpfa{n}',f'du_tpfa{n}') if population.layout.retention=='S' else ())
    need(tuple(f for f,_ in RB._SAMPLE_FAMS+RB._DIR_FAMS)==_FAMILIES,'reader family drift')
    rels=[f'corpus_staging/{RB._DIRS[s]}/shard_{i:04d}' for s,i in shards]
    members=tuple(f+'.float64.npy' for f in families)+_SHARD_JSONL+('shard_manifest.json',)
    return dict(sid=[RB._sample_id(s,l) for s,c in zip(RB._SPLITS,population.counts) for l in range(c)],
                shard=rels,split_shard=[f'{s}/{i}' for s,i in shards],
                shard_file={'members':members,'families':families},rels=rels)

def _expand(subject, subjects):
    if subject in ('unreachable','dispatcher'):return []
    if subject in ('sid','shard','split_shard'):return subjects[subject]
    kind,value=subject
    if kind=='const':return [value]
    if kind=='set':return list(value)
    names=subjects['shard_file'].get(value,value) if type(value) is str else value
    return [f'{rel}/{name}' for rel in subjects['rels'] for name in names]

def readback_diagnostics_bound(population):
    """Canonical length of the reader's sorted diagnostics list, per pass.

    Each triple is ASCII: len(["k","s","c"]) = len(k)+len(s)+len(c)+10. Sites
    are summed with their full subject populations (duplicates only loosen);
    capped sites take their longest subjects. 'unreachable' sites cannot fire
    after the exact file+directory membership check that precedes each pass
    (custody file_population equals the reader's expected names, tested for
    every layout), given exclusive custody during it.
    """
    subjects=_readback_subjects(population);total=0
    for _,kind,subject,codes,cap in READBACK_SITES:
        values=sorted((len(s) for s in _expand(subject,subjects)),reverse=True)
        if cap is not None:values=values[:cap]
        total+=sum(len(kind)+v+len(c)+10+1 for v in values for c in codes)
    return total+1

def readback_result_bound(population):
    """Canonical length of validate_corpus(...)'s result, per pass (result() mirrored)."""
    from operatormark_corpus_v2 import readback as RB
    subjects=_readback_subjects(population);ids=subjects['sid']
    N,D,S=population.samples,population.directions,len(population.shards())
    by={'relaxed':[i for i in ids if int(i[-6:])%2==0],'binary':[i for i in ids if int(i[-6:])%2==1]}
    variants=[
        dict(state='not_applicable_unconfirmed_field',trigger='confirmed_only',cap_per_stratum=64,
             anomalies_retained=dict(relaxed=N,binary=N),physical_qualification='not_confirmed'),
        dict(state='not_verified',reason='no expected anomaly procedure'),
        dict(state='no_anomalies',relaxed='unchanged',binary='unchanged'),
        {'state':'evaluated','anomalies_lower_bound':2*N,'unwritten_samples_unverified':N,'relaxed':'not_confirmed',
         'binary':'not_confirmed','independently_verified_ladders':N,'note':LADDER_NOTE}]
    ladders=max(variants,key=lambda v:len(C.canonical_json_bytes(v)))
    worst={'status':'incomplete','diagnostics':[],
        'checked':{'samples':N,'directions':D,'native_numerics_checked':N,'p1_resolved':N,'numerics':'structural',
                   'p1':'resolve','shards_expected':S,'shards_written':S,'direction_rule_rederived':False},
        'recomputed':{'gate_failures':{g:ids for g in RB._GATES},'anomalies':by,
                      'delta_max':{'relaxed':WORST_HEX,'binary':WORST_HEX},'failures_retained':ids,
                      'unwritten_measurements':ids,'anomalies_claimed_in_unwritten_shards':by},
        'writer_claims':'consistent','anomaly_field_status':ladders,
        'd10':{'verdict':'not_accepted','reasons':['consistency mismatch',
               'hard gate failures: '+', '.join(sorted(RB._GATES)),f'{N} retained sample failures',
               'anomaly ladders missing','anomaly procedure not verified','anomaly field qualification not confirmed']},
        'production_usable':False}
    return len(C.canonical_json_bytes(worst))-2+readback_diagnostics_bound(population)

LADDER_NOTE = ("Only independently re-executed ladders establish physical status; writer numbers alone "
               "leave mandatory checks incomplete. Unwritten sample anomaly claims remain unverified.")

def readback_records_bound(population):
    """State 6 readback_1 and (native, 1-64 anomalies) readback_2 custody records.

    Event count: a pass starts only when the evidence root holds exactly the
    executor's own events and the payload root exactly the staged population.
    Records are append-only with index-and-kind names, so after any executor
    writes, no other (forked) executor's event list equals the root again; the
    phase check stops a second stage6 on the same executor. Hence <= 2 records
    per attempt. custody.write_record frames each result as canonical {schema,
    kind, synthetic, previous_sha256, value, record_self_sha256}; each record is
    an exclusive publish (temporary + final name both counted). Copies embedded
    in handoff records and the audit archive belong to custody_records and B.
    """
    need(type(population) is Population,'exact population required')
    check_sources(READBACK_SOURCES)
    frame=dict(schema='corpus_v2_custody.v1',kind='readback_1',synthetic=False,previous_sha256=HEX,value=None,
               record_self_sha256=HEX)
    record=len(C.canonical_json_bytes(frame))-len('null')+readback_result_bound(population)
    return dict(bytes=2*2*record,record_bytes=record,passes=2,names_per_record=2,
        exclusive_custody_verified=False,
        admission_dependency='independent production premise P covering both roots continuously during State 6',
        precondition='before each pass: evidence root == own events and exact payload file+directory membership; '
                     'exclusive custody of both roots during the pass (no entry created, removed or modified)',
        source_hashes=dict(READBACK_SOURCES))

