def generation_run_exception_bound(population):
    """Adopted retained bytes; no guarantee about formatting time or memory.

    One unexpected_failure record plus its possible partial slot, and one
    workflow failure with canonical envelope. Workflow exclusive writes have
    temporary/final names. Extra stream rendering is counted in stream domain.
    Two names per exclusive publication, never a lossless-rendering claim.
    """
    from .bounded_exception import record_bound
    check_sources(CONFIGURATION_SUMMARY_SOURCES)
    phases=('new','state5','staged','state6','verified','finalizing','published','terminal','closed')
    # Subtract JSON null's four bytes before substituting the renderer bound.
    unexpected=len(C.canonical_json_bytes({'exception':None}))-4+record_bound()
    custody_failure=max(len(C.canonical_json_bytes(dict(schema='corpus_v2_custody.v1',kind='failure',
        synthetic=False,previous_sha256='f'*64,record_self_sha256='f'*64,
        value=dict(phase=phase,exception=None,staging_exists=False,published_exists=False,
                   disposition='retain_every_partial_no_retry'))))-4+record_bound() for phase in phases)
    return dict(bytes=run_record_bound(population)['bytes']+2*unexpected+2*custody_failure,
        unexpected_failure_slot_bytes=unexpected,custody_failure_slot_bytes=custody_failure,
        exception_record_slots=4,rendering_time_or_memory_bound=None,
        retention_policy='A_16MiB_head_tail_omission',continuous_custody_required=True)


def host_stream_bound(*,launches,retained_copies):
    from .bounded_stream import QUOTA_BYTES
    need(type(launches) is int and launches>0 and type(retained_copies) is int and retained_copies>0,
         'independently selected launch and copy populations required')
    # Metadata is not guessed: source-specific envelopes must be added by caller.
    return dict(retained_stream_bytes=launches*2*QUOTA_BYTES*retained_copies,
        metadata_bytes=None,emitted_bytes_bound=None,observed_discarded_may_exist=True,
        overflow_acceptable=False,archive_copies_included=False)


