def provider_guard_bound(*, policy, slot_id, observer_id, clock_epoch_id, child_root_binding_id,
                         parent_root_binding_id, creation_file, exit_address, exit_file_bytes_max):
    """Exact per-launch ChildGuard/parent guard bytes from ACTUAL bound inputs.

    Population is producer-enforced: coverage_start, <= sum(authorized_counts)
    counted authorized events (a call beyond its count is a denial), <= 1 denied
    event (fail-fast), 4 RNG checkpoints, policy/installed records, then either
    exit_ready or the violation (+ <= 1 source-invalidation) record; the parent
    adds process_exit/coverage_end/lifetime only after actual closure. Each
    RecordStore record is one exclusive name. Every record size is the canonical
    encoder applied to the supplied strings and the widest validator-accepted
    enumeration/number, never a supplied cap. Conditional on the cooperative
    reviewed-source premise (only guard methods emit events) and P.
    """
    from dataclasses import asdict
    from . import state_child_guard as G, state_guard_capture as E, state_execution_authority as a
    from .state_host_sizing import encoded_worst_character, json_encoding
    check_sources(GUARD_SOURCES)
    need(type(policy) is G.GuardPolicy and policy.required_hooks == G.HOOKS, 'actual bound guard policy required')
    for value in (observer_id, clock_epoch_id, child_root_binding_id, parent_root_binding_id):
        a.text(value)
    a.digest(slot_id); a.ref(creation_file); a.address(exit_address)
    need(type(exit_file_bytes_max) is int and exit_file_bytes_max > 0, 'process-exit record bound required')
    counts = dict(policy.authorized_counts)
    need(len(counts) == len(policy.authorized_counts) and
         all(k[0] in E.AUTHORIZED and type(v) is int and v >= 0 for k, v in counts.items()), 'exact authorized counts')
    authorized = sum(counts.values()); top = authorized + 2      # largest event sequence
    need(top < 10**8, 'eight-digit child event names')
    size = lambda value: len(json_encoding(value))
    widest = lambda *values: max(values, key=lambda v: len(a.canonical(v)))
    root = widest(child_root_binding_id, parent_root_binding_id)
    exit_ref = dict(exit_address, file_bytes=exit_file_bytes_max, file_sha256=HEX)
    subject = widest(creation_file, exit_ref)
    shapes = [(k, o, s, d, c, e) for k in ('coverage_start', 'operation', 'coverage_end', 'process_exit')
              for o in (*E.AUTHORIZED, *E.FORBIDDEN, 'lifetime') for s in (None, *E.records.SPLITS)
              for d in ('allowed', 'denied', 'unavailable') for c in E.records.CALLS for e in E.records.EFFECTS]
    event = 0
    while True:   # prior_event_file carries an event size: least fixed point
        prior = dict(root_binding_id=root, relative_path='guard_process_exit.json', file_bytes=event, file_sha256=HEX)
        best = 0
        for k, o, s, d, c, e in shapes:
            try:
                data = E.make_guard_event(launch_slot_id=slot_id, observer_id=observer_id, clock_epoch_id=clock_epoch_id,
                    sequence=top, kind=k, operation=o, split=s, decision=d, call_status=c, effect_status=e,
                    subject_file=subject, prior_event_file=prior)
            except Exception:
                continue
            best = max(best, len(data))
        need(best > 0, 'no validator-accepted guard event shape')
        if best == event:
            break
        event = best
    child_ref = lambda name, n: dict(root_binding_id=child_root_binding_id, relative_path=name, file_bytes=n, file_sha256=HEX)
    policy_bytes = size(json.loads(json.dumps(asdict(policy))))
    checkpoint = max(size(dict(slot_id=slot_id, checkpoint=c, numpy_legacy_sha256=HEX, python_random_sha256=HEX))
                     for c in E.CHECKPOINTS)
    installed = size(dict(source_commitment=policy.source_commitment, hooks=list(G.HOOKS), monitoring_mask=2**32 - 1,
        thread_scope='all interpreter threads; new threads denied',
        terminal_boundary='held os._exit; no Python finalizers or exit handlers', production_accepted=False))
    events = [child_ref(f'guard_{i:08d}.json', event) for i in range(authorized + 1)]
    ready = size(dict(slot_id=slot_id, source_commitment=policy.source_commitment,
        policy_file=child_ref('guard_policy.json', policy_bytes), hooks=list(G.HOOKS), events=events,
        rng_checkpoint_files={c: child_ref(f'rng_{c}.json', checkpoint) for c in E.CHECKPOINTS}, failed=False,
        exit_code=-2**31, exit_primitive='os._exit', no_python_finalization=True))
    denied_ref = child_ref(f'guard_{authorized + 1:08d}.json', event)
    violation = max(size(dict(slot_id=slot_id, family=f, denied_event_file=ref, denied_event_unavailable=why,
        exit_code=G.VIOLATION_EXIT_CODE, exit_primitive='os._exit', fail_fast=True, lifetime_evidence_written=False,
        production_accepted=False)) for f in E.FORBIDDEN
        for ref, why in ((denied_ref, None), (None, encoded_worst_character(json_encoding) * 128)))  # actual JSON serializer; validation stays strict
    invalidation = size(dict(reason='held_source_integrity_failed', slot_id=slot_id))
    lifetime = size(dict(slot_id=slot_id, observer_id=observer_id, clock_epoch_id=clock_epoch_id,
        creation_file=creation_file, exit_file=exit_ref, first_sequence=0, last_sequence=top,
        started_before_project_import=True, through_direct_exit=True, hooks=list(G.HOOKS)))
    child = policy_bytes + installed + 4*checkpoint + (authorized + 2)*event + max(ready, violation + invalidation)
    parent = 2*event + lifetime
    # policy, installed, 4 checkpoints, events, ready | (violation + invalidation); parent 2 events + lifetime
    names = 2 + 4 + (authorized + 2) + 2 + 3
    return dict(bytes=child + parent, names=names, event_record_bytes=event,
        child_events_max=authorized + 2, denied_events_max=1, authorized_events_max=authorized,
        child_bytes=child, parent_bytes=parent, exit_ready_bytes=ready, violation_bytes=violation,
        source_invalidation_bytes=invalidation, lifetime_bytes=lifetime, policy_bytes=policy_bytes,
        fail_fast_exit_code=G.VIOLATION_EXIT_CODE, conditional_on=('reviewed cooperative guard source', 'P'),
        excludes=('process creation/exit/stream records', 'phase storage observations', 'archive/support copies'))


